23	/// Provides semantic APIs to manipulate the layer map.
24	pub(crate) enum LayerManager {
25	    /// Open as in not shutdown layer manager; we still have in-memory layers and we can manipulate
26	    /// the layers.
27	    Open(OpenLayerManager),
28	    /// Shutdown layer manager where there are no more in-memory layers and persistent layers are
29	    /// read-only.
30	    Closed {
31	        layers: HashMap<PersistentLayerKey, Layer>,
32	    },
33	}
34	
35	impl Default for LayerManager {
36	    fn default() -> Self {
37	        LayerManager::Open(OpenLayerManager::default())
38	    }
39	}
40	
41	impl LayerManager {
42	    fn upgrade(&self, weak: ReadableLayerWeak) -> ReadableLayer {
43	        match weak {
44	            ReadableLayerWeak::PersistentLayer(desc) => {
45	                ReadableLayer::PersistentLayer(self.get_from_desc(&desc))
46	            }
47	            ReadableLayerWeak::InMemoryLayer(desc) => {
48	                let inmem = self
49	                    .layer_map()
50	                    .expect("no concurrent shutdown")
51	                    .in_memory_layer(&desc);
52	                ReadableLayer::InMemoryLayer(inmem)
53	            }
54	        }
55	    }
56	
57	    pub(crate) fn get_from_key(&self, key: &PersistentLayerKey) -> Layer {
58	        // The assumption for the `expect()` is that all code maintains the following invariant:
59	        // A layer's descriptor is present in the LayerMap => the LayerFileManager contains a layer for the descriptor.
60	        self.try_get_from_key(key)
61	            .with_context(|| format!("get layer from key: {key}"))
62	            .expect("not found")
63	            .clone()
64	    }
65	
66	    pub(crate) fn try_get_from_key(&self, key: &PersistentLayerKey) -> Option<&Layer> {
67	        self.layers().get(key)
68	    }
69	
70	    pub(crate) fn get_from_desc(&self, desc: &PersistentLayerDesc) -> Layer {
71	        self.get_from_key(&desc.key())
72	    }
73	
74	    /// Get an immutable reference to the layer map.
75	    ///
76	    /// We expect users only to be able to get an immutable layer map. If users want to make modifications,
77	    /// they should use the below semantic APIs. This design makes us step closer to immutable storage state.
78	    pub(crate) fn layer_map(&self) -> Result<&LayerMap, Shutdown> {
79	        use LayerManager::*;
80	        match self {
81	            Open(OpenLayerManager { layer_map, .. }) => Ok(layer_map),
82	            Closed { .. } => Err(Shutdown),
83	        }
84	    }
85	
86	    pub(crate) fn open_mut(&mut self) -> Result<&mut OpenLayerManager, Shutdown> {
87	        use LayerManager::*;
88	
89	        match self {
90	            Open(open) => Ok(open),
91	            Closed { .. } => Err(Shutdown),
92	        }
93	    }
94	
95	    /// LayerManager shutdown. The in-memory layers do cleanup on drop, so we must drop them in
96	    /// order to allow shutdown to complete.
97	    ///
98	    /// If there was a want to flush in-memory layers, it must have happened earlier.
99	    pub(crate) fn shutdown(&mut self, writer_state: &mut Option<TimelineWriterState>) {
100	        use LayerManager::*;
101	        match self {
102	            Open(OpenLayerManager {
103	                layer_map,
104	                layer_fmgr: LayerFileManager(hashmap),
105	            }) => {
106	                // NB: no need to decrement layer metrics; metrics are removed on timeline shutdown.
107	                let open = layer_map.open_layer.take();
108	                let frozen = layer_map.frozen_layers.len();
109	                let taken_writer_state = writer_state.take();
110	                tracing::info!(open = open.is_some(), frozen, "dropped inmemory layers");
111	                let layers = std::mem::take(hashmap);
112	                *self = Closed { layers };
113	                assert_eq!(open.is_some(), taken_writer_state.is_some());
114	            }
115	            Closed { .. } => {
116	                tracing::debug!("ignoring multiple shutdowns on layer manager")
117	            }
118	        }
119	    }
120	
121	    /// Sum up the historic layer sizes
122	    pub(crate) fn layer_size_sum(&self) -> u64 {
123	        self.layers()
124	            .values()
125	            .map(|l| l.layer_desc().file_size)
126	            .sum()
127	    }
128	
129	    pub(crate) fn likely_resident_layers(&self) -> impl Iterator<Item = &'_ Layer> + '_ {
130	        self.layers().values().filter(|l| l.is_likely_resident())
131	    }
132	
133	    pub(crate) fn visible_layers(&self) -> impl Iterator<Item = &'_ Layer> + '_ {
134	        self.layers()
135	            .values()
136	            .filter(|l| l.visibility() == LayerVisibilityHint::Visible)
137	    }
138	
139	    pub(crate) fn contains(&self, layer: &Layer) -> bool {
140	        self.contains_key(&layer.layer_desc().key())
141	    }
142	
143	    pub(crate) fn contains_key(&self, key: &PersistentLayerKey) -> bool {
144	        self.layers().contains_key(key)
145	    }
146	
147	    pub(crate) fn all_persistent_layers(&self) -> Vec<PersistentLayerKey> {
148	        self.layers().keys().cloned().collect_vec()
149	    }
150	
151	    /// Update the [`LayerFringe`] of a read request
152	    ///
153	    /// Take a key space at a given LSN and query the layer map below each range
154	    /// of the key space to find the next layers to visit.
155	    pub(crate) fn update_search_fringe(
156	        &self,
157	        keyspace: &KeySpace,
158	        cont_lsn: Lsn,
159	        fringe: &mut LayerFringe,
160	    ) -> Result<(), Shutdown> {
161	        let map = self.layer_map()?;
162	
163	        for range in keyspace.ranges.iter() {
164	            let results = map.range_search(range.clone(), cont_lsn);
165	            results
166	                .found
167	                .into_iter()
168	                .map(|(SearchResult { layer, lsn_floor }, keyspace_accum)| {
169	                    (
170	                        self.upgrade(layer),
171	                        keyspace_accum.to_keyspace(),
172	                        lsn_floor..cont_lsn,
173	                    )
174	                })
175	                .for_each(|(layer, keyspace, lsn_range)| fringe.update(layer, keyspace, lsn_range));
176	        }
177	
178	        Ok(())
179	    }
180	
181	    fn layers(&self) -> &HashMap<PersistentLayerKey, Layer> {
182	        use LayerManager::*;
183	        match self {
184	            Open(OpenLayerManager { layer_fmgr, .. }) => &layer_fmgr.0,
185	            Closed { layers } => layers,
186	        }
187	    }
188	}
