197	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
198	        f.debug_struct("OpenLayerManager")
199	            .field("layer_count", &self.layer_fmgr.0.len())
200	            .finish()
201	    }
202	}
